import { AddScheduledMaintenanceCalendarFeed1803450000000 } from "../../../../Server/Infrastructure/Postgres/SchemaMigrations/1803450000000-AddScheduledMaintenanceCalendarFeed";
import SchemaMigrations from "../../../../Server/Infrastructure/Postgres/SchemaMigrations/Index";
import { MigrationInterface, QueryRunner } from "typeorm";
import fs from "fs";
import path from "path";
import { beforeAll, describe, expect, test } from "@jest/globals";

/*
 * The migration was generated by TypeORM against a fully migrated throwaway
 * database; what is pinned is what it must hold: the one new table and
 * nothing else (a generator pointed at a drifted database emits changes to
 * unrelated tables), the uniqueness rules the routes and the service rely on
 * (one link per project, one row per token hash), rows that go with their
 * project, and a down() that undoes all of it.
 */

const MIGRATION_NAME: string =
  "AddScheduledMaintenanceCalendarFeed1803450000000";
const TIMESTAMP: number = 1803450000000;
const TABLE: string = "ScheduledMaintenanceCalendarFeed";

const CREATE_TABLE_PATTERN: RegExp = /^CREATE TABLE "([A-Za-z]+)"/;
const INDEX_NAME_PATTERN: RegExp = /CREATE (?:UNIQUE )?INDEX "([^"]+)"/;
const TABLE_MENTION_PATTERN: RegExp = /(?:TABLE|ON|REFERENCES) "([A-Za-z]+)"/g;
const TRAILING_TIMESTAMP_PATTERN: RegExp = /(\d+)$/;
const UNIQUE_PROJECT_INDEX: RegExp =
  /^CREATE UNIQUE INDEX "IDX_[0-9a-f]+" ON "ScheduledMaintenanceCalendarFeed" \("projectId"\) $/;
const PREVIOUS_HASH_INDEX: RegExp =
  /^CREATE INDEX "IDX_[0-9a-f]+" ON "ScheduledMaintenanceCalendarFeed" \("previousTokenHash"\) $/;

type MigrationClass = new () => MigrationInterface;

async function run(direction: "up" | "down"): Promise<Array<string>> {
  const queries: Array<string> = [];

  const runner: QueryRunner = {
    query: async (sql: string): Promise<void> => {
      queries.push(sql);
    },
  } as unknown as QueryRunner;

  const migration: AddScheduledMaintenanceCalendarFeed1803450000000 =
    new AddScheduledMaintenanceCalendarFeed1803450000000();

  if (direction === "up") {
    await migration.up(runner);
  } else {
    await migration.down(runner);
  }

  return queries;
}

let up: Array<string> = [];
let down: Array<string> = [];

beforeAll(async () => {
  up = await run("up");
  down = await run("down");
});

function createTable(): string {
  const statement: string | undefined = up.find((sql: string) => {
    return sql.startsWith(`CREATE TABLE "${TABLE}" (`);
  });

  if (!statement) {
    throw new Error(`No CREATE TABLE for ${TABLE}`);
  }

  return statement;
}

describe("AddScheduledMaintenanceCalendarFeed migration", () => {
  test("names itself after its timestamp", () => {
    expect(AddScheduledMaintenanceCalendarFeed1803450000000.name).toBe(
      MIGRATION_NAME,
    );
    expect(new AddScheduledMaintenanceCalendarFeed1803450000000().name).toBe(
      MIGRATION_NAME,
    );
  });

  test("is registered exactly once, after every migration older than it", () => {
    const registered: Array<MigrationClass> =
      SchemaMigrations as Array<MigrationClass>;

    expect(
      registered.filter((migration: MigrationClass) => {
        return migration === AddScheduledMaintenanceCalendarFeed1803450000000;
      }),
    ).toHaveLength(1);

    const index: number = registered.indexOf(
      AddScheduledMaintenanceCalendarFeed1803450000000,
    );

    for (let before: number = 0; before < index; before++) {
      const match: RegExpMatchArray | null = registered[before]!.name.match(
        TRAILING_TIMESTAMP_PATTERN,
      );

      expect(match ? parseInt(match[1]!, 10) : 0).toBeLessThan(TIMESTAMP);
    }
  });

  test("is backed by exactly one file carrying its timestamp", () => {
    const directory: string = path.join(
      __dirname,
      "../../../../Server/Infrastructure/Postgres/SchemaMigrations",
    );

    expect(
      fs.readdirSync(directory).filter((file: string) => {
        return file.startsWith(`${TIMESTAMP}-`);
      }),
    ).toEqual([`${TIMESTAMP}-AddScheduledMaintenanceCalendarFeed.ts`]);
  });

  test("creates the one new table and touches nothing but it, its project and its users", () => {
    const created: Array<string> = up
      .map((sql: string) => {
        return sql.match(CREATE_TABLE_PATTERN)?.[1] || null;
      })
      .filter((name: string | null): name is string => {
        return name !== null;
      });

    expect(created).toEqual([TABLE]);

    const mentioned: Set<string> = new Set<string>();

    for (const sql of [...up, ...down]) {
      for (const match of sql.matchAll(TABLE_MENTION_PATTERN)) {
        mentioned.add(match[1]!);
      }
    }

    expect([...mentioned].sort()).toEqual([TABLE, "Project", "User"].sort());
  });

  test("one row per token hash, the hash and the project required", () => {
    const statement: string = createTable();

    expect(statement).toContain('"tokenHash" character varying(100) NOT NULL');
    expect(statement).toContain('UNIQUE ("tokenHash")');
    expect(statement).toContain('"projectId" uuid NOT NULL');
    expect(statement).toContain('"token" text');
    expect(statement).toContain('"isEnabled" boolean NOT NULL DEFAULT true');
    expect(statement).toContain(`"fetchCount" integer NOT NULL DEFAULT '0'`);
  });

  test("one link per project, and the rotated-out hash indexed for the public lookup", () => {
    expect(up).toContainEqual(expect.stringMatching(UNIQUE_PROJECT_INDEX));
    expect(up).toContainEqual(expect.stringMatching(PREVIOUS_HASH_INDEX));
  });

  test("a project's link goes with the project; a user's removal leaves it", () => {
    expect(up).toContainEqual(
      expect.stringContaining(
        'FOREIGN KEY ("projectId") REFERENCES "Project"("_id") ON DELETE CASCADE',
      ),
    );
    expect(up).toContainEqual(
      expect.stringContaining(
        'FOREIGN KEY ("createdByUserId") REFERENCES "User"("_id") ON DELETE SET NULL',
      ),
    );
    expect(up).toContainEqual(
      expect.stringContaining(
        'FOREIGN KEY ("deletedByUserId") REFERENCES "User"("_id") ON DELETE SET NULL',
      ),
    );
  });

  test("down() drops every index up() created, and the table last", () => {
    const created: Array<string> = up
      .map((sql: string) => {
        return sql.match(INDEX_NAME_PATTERN)?.[1] || null;
      })
      .filter((name: string | null): name is string => {
        return name !== null;
      });

    expect(created).toHaveLength(2);

    for (const name of created) {
      expect(down).toContain(`DROP INDEX "public"."${name}"`);
    }

    expect(down[down.length - 1]).toBe(`DROP TABLE "${TABLE}"`);
  });
});
